import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        int n = in.nextInt();
        String s = in.nextString();
        int[] a = new int[n];
        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
            cnt[s.charAt(i) - 'a']++;
        }
        int pairCount = (n + 1) / 2;
        int V = n + 26 + 2;
        int source = V - 2;
        int sink = V - 1;
        Graph g = new Graph(V);
        for (int i = 0; i < 26; i++) {
            g.addFlowWeightedEdge(source, i + n, 0, cnt[i]);
        }
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < pairCount; j++) {
                int left = j;
                int right = n - 1 - j;
                long w = 0;
                if (s.charAt(left) == s.charAt(right)) {
                    if (s.charAt(left) == (char)('a' + i)) {
                        w = -Math.max(a[left], a[right]);
                    }
                } else {
                    if (s.charAt(left) == (char)('a' + i)) w -= a[left];
                    if (s.charAt(right) == (char)('a' + i)) w -= a[right];
                }
                g.addFlowWeightedEdge(i + n, j, w, 1);
            }
        }
        for (int j = 0; j < pairCount; j++) {
            g.addFlowWeightedEdge(j, sink, 0, 2);
        }
        MinCostFlow mcmf = new MinCostFlow(g, source, sink, true);
        out.println(-mcmf.minCostMaxFlow().first);
        out.close();
    }

    static class Graph {
        int V;
        int[] head;
        int[] to;
        int[] next;
        long[] cap;
        long[] cost;
        int[] rev;
        int edgeCount;
        Graph(int V) {
            this.V = V;
            head = new int[V];
            Arrays.fill(head, -1);
            to = new int[2];
            next = new int[2];
            cap = new long[2];
            cost = new long[2];
            rev = new int[2];
            edgeCount = 0;
        }
        void addEdge(int from, int to, long cost, long cap, int rev) {
            ensureCapacity(edgeCount + 1);
            next[edgeCount] = head[from];
            head[from] = edgeCount;
            this.to[edgeCount] = to;
            this.cost[edgeCount] = cost;
            this.cap[edgeCount] = cap;
            this.rev[edgeCount] = rev;
            edgeCount++;
        }
        void addFlowWeightedEdge(int from, int to, long cost, long cap) {
            addEdge(from, to, cost, cap, edgeCount + 1);
            addEdge(to, from, -cost, 0, edgeCount - 1);
        }
        void ensureCapacity(int size) {
            if (to.length < size) {
                int newSize = Math.max(size, 2 * to.length);
                to = Arrays.copyOf(to, newSize);
                next = Arrays.copyOf(next, newSize);
                cap = Arrays.copyOf(cap, newSize);
                cost = Arrays.copyOf(cost, newSize);
                rev = Arrays.copyOf(rev, newSize);
            }
        }
    }

    static class MinCostFlow {
        Graph g;
        int s, t;
        long[] phi;
        long[] dist;
        int[] prevv, preve;
        int[] visited;
        int visitIndex;
        MinCostFlow(Graph g, int s, int t, boolean hasNegative) {
            this.g = g;
            this.s = s;
            this.t = t;
            phi = new long[g.V];
            if (hasNegative) {
                Arrays.fill(phi, Long.MAX_VALUE);
                phi[s] = 0;
                boolean[] inQueue = new boolean[g.V];
                int[] queue = new int[g.V + 1];
                int head = 0, end = 0;
                queue[end++] = s;
                inQueue[s] = true;
                int steps = 0;
                while (head != end) {
                    int v = queue[head++];
                    if (head == queue.length) head = 0;
                    inQueue[v] = false;
                    for (int e = g.head[v]; e != -1; e = g.next[e]) {
                        if (g.cap[e] > 0) {
                            int u = g.to[e];
                            long nd = phi[v] + g.cost[e];
                            if (phi[u] > nd) {
                                phi[u] = nd;
                                if (!inQueue[u]) {
                                    queue[end++] = u;
                                    if (end == queue.length) end = 0;
                                    inQueue[u] = true;
                                }
                            }
                        }
                    }
                    if (++steps > 2 * g.V * g.V) throw new RuntimeException("Negative cycle");
                }
            }
            dist = new long[g.V];
            prevv = new int[g.V];
            preve = new int[g.V];
            visited = new int[g.V];
            visitIndex = 0;
        }
        Pair<Long, Long> minCostMaxFlow() {
            return minCostMaxFlow(Long.MAX_VALUE);
        }
        Pair<Long, Long> minCostMaxFlow(long maxf) {
            long flow = 0, cost = 0;
            while (flow < maxf) {
                Arrays.fill(dist, Long.MAX_VALUE);
                dist[s] = 0;
                // Use dense Dijkstra (O(V^2))
                visitIndex++;
                for (int i = 0; i < g.V; i++) {
                    int v = -1;
                    long best = Long.MAX_VALUE;
                    for (int j = 0; j < g.V; j++) {
                        if (visited[j] != visitIndex && dist[j] < best) {
                            best = dist[j];
                            v = j;
                        }
                    }
                    if (v == -1) break;
                    visited[v] = visitIndex;
                    for (int e = g.head[v]; e != -1; e = g.next[e]) {
                        if (g.cap[e] > 0) {
                            int u = g.to[e];
                            if (visited[u] != visitIndex) {
                                long nd = best + g.cost[e] + phi[v] - phi[u];
                                if (dist[u] > nd) {
                                    dist[u] = nd;
                                    prevv[u] = v;
                                    preve[u] = e;
                                }
                            }
                        }
                    }
                }
                if (dist[t] == Long.MAX_VALUE) break;
                for (int v = 0; v < g.V; v++) {
                    if (dist[v] < Long.MAX_VALUE) phi[v] += dist[v];
                }
                long add = maxf - flow;
                for (int v = t; v != s; v = prevv[v]) {
                    add = Math.min(add, g.cap[preve[v]]);
                }
                flow += add;
                cost += add * phi[t];
                for (int v = t; v != s; v = prevv[v]) {
                    int e = preve[v];
                    g.cap[e] -= add;
                    g.cap[g.rev[e]] += add;
                }
            }
            return new Pair<>(cost, flow);
        }
    }

    static class Pair<U, V> {
        U first;
        V second;
        Pair(U first, V second) {
            this.first = first;
            this.second = second;
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;
        public InputReader(InputStream stream) { this.stream = stream; }
        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try { numChars = stream.read(buf); } catch (IOException e) { throw new InputMismatchException(); }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }
        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10; res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }
        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
        public boolean isSpaceChar(int c) {
            if (filter != null) return filter.isSpaceChar(c);
            return isWhitespace(c);
        }
        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
        public interface SpaceCharFilter { boolean isSpaceChar(int ch); }
    }

    static class OutputWriter {
        private PrintWriter writer;
        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }
        public void close() { writer.close(); }
        public void println(long i) { writer.println(i); }
    }
}
